// genHeader is the header stamped on every generated file. It carries no
// timestamp, run id or instance URL, so a re-import of an unchanged instance
// produces identical bytes.
func genHeader(what string) string {
	return "Generated by `netbox-gitops import` from a live NetBox instance.\n" +
		"\n" +
		what + "\n" +
		"\n" +
		"This is an ordinary file now: it is applied like any other, and a\n" +
		"re-import overwrites it. Review it before committing."
}

// siteAllowed reports whether a site slug passes the --site source filter.
func (rc *runContext) siteAllowed(slug string) bool {
	if len(rc.opts.Sites) == 0 {
		return true
	}
	for _, s := range rc.opts.Sites {
		if s == slug {
			return true
		}
	}
	return false
}

// foundation imports sites, racks, roles, tags, platforms, tenant groups,
// tenants and custom fields.
func (rc *runContext) foundation() error {
	steps := []func() error{
		rc.importSites,
		rc.importRacks,
		rc.importRoles,
		rc.importTags,
		rc.importPlatforms,
		rc.importTenantGroups,
		rc.importTenants,
		rc.importCustomFields,
	}
	for _, step := range steps {
		if err := step(); err != nil {
			return err
		}
	}
	return nil
}

func (rc *runContext) importSites() error {
	objs, err := rc.f.list("dcim", "sites", nil)
	if err != nil {
		return err
	}
	var items []interface{}
	exported := 0
	for _, o := range objs {
		if !rc.keep(o) {
			continue
		}
		slug := str(o, "slug")
		if !rc.siteAllowed(slug) {
			continue
		}
		site := &models.Site{
			Name:        str(o, "name"),
			Slug:        slug,
			Status:      choiceValue(o, "status"),
			Region:      refSlug(o, "region"),
			TimeZone:    str(o, "time_zone"),
			Description: str(o, "description"),
			Comments:    str(o, "comments"),
			Tags:        tagSlugs(o, rc.strip),
		}
		if site.Region != "" {
			rc.report.note("site.region: regions are referenced but not imported as their own definitions")
		}
		items = append(items, site)
		exported++
	}
	rc.report.count("dcim/sites", len(objs), exported)
	if len(items) == 0 {
		return nil
	}
	return rc.emit("definitions/sites/sites.yaml",
		genHeader("Every site this NetBox holds."), "items", items)
}

func (rc *runContext) importRacks() error {
	objs, err := rc.f.list("dcim", "racks", nil)
	if err != nil {
		return err
	}
	var items []interface{}
	exported := 0
	for _, o := range objs {
		if !rc.keep(o) {
			continue
		}
		siteSlug := refSlug(o, "site")
		if !rc.siteAllowed(siteSlug) {
			continue
		}
		rack := &models.Rack{
			Name: str(o, "name"),
			// NetBox racks have no slug of their own; the YAML slug is this
			// project's concept, derived from the name and reused verbatim by
			// every device's rack_slug.
			Slug:        utils.Slugify(str(o, "name")),
			SiteSlug:    siteSlug,
			Status:      choiceValue(o, "status"),
			Width:       intOf(o, "width"),
			UHeight:     intOf(o, "u_height"),
			Description: str(o, "description"),
			Tags:        tagSlugs(o, rc.strip),
		}
		if w := nested(o, "width"); w != nil {
			// width serialises as a choice on some releases.
			rack.Width = intOf(client.Object(w), "value")
		}
		items = append(items, rack)
		exported++
	}
	rc.report.count("dcim/racks", len(objs), exported)
	if len(items) == 0 {
		return nil
	}
	return rc.emit("definitions/racks/racks.yaml",
		genHeader("Every rack this NetBox holds. The slug is derived from the name;\n"+
			"devices reference it by that slug."), "items", items)
}

