func (rc *runContext) importTags() error {
	objs, err := rc.f.list("extras", "tags", nil)
	if err != nil {
		return err
	}
	var items []interface{}
	exported := 0
	for _, o := range objs {
		slug := str(o, "slug")
		// The managed tag (and any sandbox tag) is machinery, not data: the
		// sync recreates the managed tag itself, so importing it would be noise.
		if rc.strip[slug] {
			continue
		}
		if !rc.keep(o) {
			continue
		}
		items = append(items, &models.Tag{
			Name:        str(o, "name"),
			Slug:        slug,
			Color:       utils.NormalizeColor(str(o, "color")),
			Description: str(o, "description"),
		})
		exported++
	}
	rc.report.count("extras/tags", len(objs), exported)
	if len(items) == 0 {
		return nil
	}
	return rc.emit("definitions/extras/tags.yaml",
		genHeader("Every tag this NetBox holds, except the gitops-managed tag the\n"+
			"sync maintains itself."), "items", items)
}

